import { Component, ElementRef, EventEmitter, inject, Input, Output } from '@angular/core';
import { ReactiveFormsModule, Validators } from '@angular/forms';
import { ButtonComponent } from 'espd-common/button';
import { FormsModule, SelectOption } from 'espd-common/forms';
import { EspdFormControl, EspdFormGroup } from 'espd-common/forms/api';
import { DatePickerComponent } from 'espd-common/forms/date-picker';
import { EspdValidators } from 'espd-common/forms/validators';
import { MessageConfig, MessageModule } from 'espd-common/i18n';
import { IconDirective } from 'espd-common/icon';
import { BsDatepickerConfig, BsDatepickerModule } from 'ngx-bootstrap/datepicker';

export type ListElementType = string | Date | object;

@Component({
	selector: 'espd-list-builder',
	templateUrl: './list-builder.component.html',
	imports: [
		ButtonComponent,
		ReactiveFormsModule,
		BsDatepickerModule,
		IconDirective,
		FormsModule,
		MessageModule,
		DatePickerComponent
	],
	styleUrls: ['./list-builder.component.scss']
})
export class ListBuilderComponent {

	@Input()
	public maxHeight: number | null = null;

	@Input()
	public maxLength?: number;

	@Input()
	public hideInput = false;

	@Input()
	public contentMargin = true;

	@Input()
	public inputButtonIcon = 'rvt-magnifying-glass';

	@Input()
	public inputButtonText: MessageConfig | string = '';

	@Input()
	public inputPlaceholder: MessageConfig | string = '';

	@Input()
	public inputAriaLabelledBy: string | null = null;

	@Input()
	public datePickerConfig?: Partial<BsDatepickerConfig>;

	@Input()
	public selectOptions?: SelectOption[];

	@Input()
	public required = false;

	@Output()
	public readonly submitInput = new EventEmitter<ListElementType>();

	public form: EspdFormGroup<{ listItem: EspdFormControl<ListElementType> }>;

	private element = inject<ElementRef<HTMLElement>>(ElementRef);

	public constructor() {
		this.form = new EspdFormGroup({
			listItem: new EspdFormControl<ListElementType>(null, Validators.compose([
				EspdValidators.conditional(() => !!this.maxLength, Validators.maxLength(this.maxLength!)),
				EspdValidators.conditional(() => this.required, Validators.required)
			]))
		});
	}

	public clearInput(): void {
		this.form.reset();
	}

	public focusOnInput(): void {
		this.element.nativeElement.querySelector<HTMLElement>('input, select')?.focus();
	}

	public addItem(event?: Event): void {
		event?.preventDefault();
		event?.stopPropagation();
		if (this.form.valid) {
			this.submitInput.emit(this.form.value.listItem ?? undefined);
		}
	}
}