import { CdkDragDrop, DragDropModule, moveItemInArray } from '@angular/cdk/drag-drop';
import { CommonModule } from '@angular/common';
import {
	AfterViewInit,
	Component,
	ElementRef,
	HostListener,
	Injector,
	Input,
	QueryList,
	TemplateRef,
	ViewChild,
	ViewChildren,
	forwardRef,
	inject
} from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ButtonComponent } from 'espd-common/button';
import { SelectOption } from 'espd-common/forms';
import { EspdAbstractInputDirective, EspdFormControl, espdAbstractInputComponentInjectionToken } from 'espd-common/forms/api';
import { InputScaffoldComponent } from 'espd-common/forms/input-scaffold';
import { MessageModule } from 'espd-common/i18n';
import { IconDirective } from 'espd-common/icon';
import { ModalService } from 'espd-common/modal';
import { BsDatepickerConfig } from 'ngx-bootstrap/datepicker';
import { takeUntil } from 'rxjs';
import { ListBuilderComponent, ListElementType } from '../list-builder/list-builder.component';

@Component({
	selector: 'espd-list-input',
	templateUrl: './list-input.component.html',
	imports: [
		CommonModule,
		FormsModule,
		ButtonComponent,
		IconDirective,
		InputScaffoldComponent,
		ListBuilderComponent,
		MessageModule,
		DragDropModule
	],
	styleUrls: ['./list-input.component.scss'],
	providers: [
		{ provide: espdAbstractInputComponentInjectionToken, useExisting: forwardRef(() => ListInputComponent) }
	]
})
export class ListInputComponent<T extends ListElementType = string> extends EspdAbstractInputDirective<EspdFormControl<T[]>> implements AfterViewInit {

	@Input()
	public itemTemplate: TemplateRef<unknown> | null = null;

	//Controls display of custom form controls
	@Input()
	public formDisplay: 'none' | 'modal' | 'inline' = 'none';

	@Input()
	public listOnly = false;

	@Input()
	public maxLength?: number;

	@Input()
	public beforeAdd?: (item: T) => boolean;

	@Input()
	public beforeRemove?: (item: T) => boolean;

	@Input()
	public evaluateForm?: () => T | null;

	@Input()
	public resetForm?: (item: T | null) => void;

	@Input()
	public ordered = false;

	@Input()
	public datePickerConfig?: Partial<BsDatepickerConfig>;

	@Input()
	public selectOptions?: SelectOption[];

	@ViewChild(ListBuilderComponent)
	private listBuilderComponent?: ListBuilderComponent;

	@ViewChildren('listItem')
	public listItems!: QueryList<ElementRef>;

	@ViewChild('ngContentTemplate')
	private contentTemplate!: TemplateRef<unknown>;

	public editingIndex: number | null = null;
	private itemToFocus?: [number, boolean];

	private modalService = inject(ModalService);

	public constructor() {
		super(inject(Injector));
	}

	public get hasItems(): boolean {
		const value = this.control.value;
		return Array.isArray(value) && value.length > 0;
	}

	public get isCustomFormDisplayNone(): boolean {
		return this.formDisplay === 'none';
	}

	public get isCustomInlineForm(): boolean {
		return this.formDisplay === 'inline';
	}

	public get isCustomModalForm(): boolean {
		return this.formDisplay === 'modal';
	}

	public add(item: T): void {
		if (!this.beforeAdd || this.beforeAdd(item)) {
			const value = this.control.value;
			if (Array.isArray(value)) {
				value.push(item);
				this.setValue(value);
				this.listBuilderComponent?.clearInput();
				this.listBuilderComponent?.focusOnInput();
			} else {
				console.warn('Cannot add to a non-array value')
			}
		}
	}

	public remove(item: T): void {
		if (!this.beforeRemove || this.beforeRemove(item)) {
			const value = this.control.value;
			if (Array.isArray(value)) {
				value.splice(value.indexOf(item), 1)
				this.setValue(value);
			}
		}
	}

	public openModal(): void {
		this.modalService.show<boolean>({ key: 'common.listInput.modal.title' }, this.contentTemplate, [
			{ content: { key: 'common.add' }, value: true },
			{ content: { key: 'common.cancel' }, secondary: true, value: false }
		], {
			dismissable: true
		}).subscribe(value => {
			if (value) {
				this.addComplex();
			} else {
				this.editingIndex = null;
			}
		})
	}

	public addComplex(): void {
		const item: T | null = this.evaluateForm?.() ?? null;
		if (item) {
			if (this.isEditing) {
				this.merge(item, this.editingIndex!);
				this.editingIndex = null;
			} else {
				this.add(item);
			}
			this.resetForm?.(null);
		}
	}

	public editComplex(item: T): void {
		this.resetForm?.(item);
		if (this.isCustomModalForm) {
			this.openModal();
		}
		this.editingIndex = this.control.value!.indexOf(item);
	}

	public get isEditing(): boolean {
		return this.editingIndex != null;
	}

	public cancelEdit(): void {
		this.resetForm?.(null);
		this.editingIndex = null;
	}

	private merge(updated: T, index: number) {
		const array = this.control.value ?? [];
		const current = array[index];
		if (!(updated instanceof Date) && typeof updated === 'object' && typeof current === 'object') {
			updated = { ...current, ...updated };
		}
		array[index] = updated;
		this.setValue(array);
	}

	private setValue(value: any[]) {
		this.control.setValue(value);
		this.control.markAsDirty();
		this.control.markAllAsTouched();
	}

	@HostListener('keydown', ['$event'])
	public handleKeyboardEvent(event: KeyboardEvent): void {
		if (['ArrowDown', 'ArrowUp'].includes(event.key)) {
			event.preventDefault();
		}
	}

	public ngAfterViewInit(): void {
		this.listItems.changes.pipe(takeUntil(this.ngUnsubscribe)).subscribe(() => {
			if (this.itemToFocus !== undefined) {
				const tileElement = this.listItems.get(this.itemToFocus[0])?.nativeElement as HTMLElement;
				tileElement.focus();
				if (this.itemToFocus[1]) {
					tileElement.scrollIntoView({ behavior: 'smooth', block: 'center' });
				}
				this.itemToFocus = undefined;
			}
		});
	}

	/*
	// Drag and Drop
	*/
	public reorderDroppedItem(event: CdkDragDrop<any[]>): void {
		if (event.previousIndex !== event.currentIndex) {
			this.moveItem(event.previousIndex, event.currentIndex);
		}
	}

	public moveItemUp(index: number): void {
		if (this.ordered && index > 0) {
			this.moveItem(index, index - 1);
		}
	}

	public moveItemDown(index: number): void {
		const value = this.control.value;
		if (this.ordered && Array.isArray(value) && index < value.length) {
			this.moveItem(index, index + 1);
		}
	}

	private moveItem(previousIndex: number, currentIndex: number, scroll = false) {
		const value = this.control.value;
		if (Array.isArray(value)) {
			moveItemInArray(value, previousIndex, currentIndex);
			this.itemToFocus = [currentIndex, scroll];
		}
	}

	public focus(target: 'control' | 'container' = 'control'): void {
		if (target === 'control') {
			this.listBuilderComponent?.focusOnInput()
		} else {
			throw new Error('Method not implemented.');
		}
	}
}