import { CommonModule } from '@angular/common';
import {
	Component,
	forwardRef,
	Input,
	TemplateRef,
	ViewChild
} from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ButtonModule } from 'espd-common/button';
import { ControlNameModule, espdAbstractInputComponentInjectionToken, EspdAbstractInputDirective } from 'espd-common/forms/api';
import { InputScaffoldComponent } from 'espd-common/forms/input-scaffold';
import { MessageModule } from 'espd-common/i18n';
import { RowItem } from 'espd-common/layout/table';
import { ListBuilderComponent } from '../list-builder/list-builder.component';

@Component({
	selector: 'espd-item-picker',
	templateUrl: './item-picker.component.html',
	imports: [
		CommonModule,
		FormsModule,
		ControlNameModule,
		ButtonModule,
		InputScaffoldComponent,
		MessageModule,
		ListBuilderComponent
	],
	styleUrls: ['./item-picker.component.scss'],
	providers: [{ provide: espdAbstractInputComponentInjectionToken, useExisting: forwardRef(() => ItemPickerComponent) }]
})
export class ItemPickerComponent extends EspdAbstractInputDirective {

	@Input()
	public searchFunction?: (terms: string) => RowItem[] | Promise<RowItem[]>;

	@Input()
	public itemTemplate: TemplateRef<any> | null = null;

	@Input()
	public maxHeight = 400;

	@Input()
	public rowDimmingFunction?: (item: RowItem, index: number) => boolean;

	@ViewChild(ListBuilderComponent)
	private listBuilderComponent!: ListBuilderComponent;

	public items?: RowItem[];

	public get hasItems(): boolean {
		return (this.items?.length ?? 0) > 0;
	}

	public async search(terms: string): Promise<void> {
		this.items = await this.searchFunction?.(terms) ?? [];
	}

	public select(item: RowItem): void {
		this.setValue(item);
	}

	public change(): void {
		this.setValue(null);

		this.items = [];
		setTimeout(() => {
			this.listBuilderComponent.focusOnInput();
		});
	}

	public dimRow(item: RowItem, index: number): boolean {
		return this.rowDimmingFunction?.(item, index) ?? false;
	}

	private setValue(item: RowItem | null) {
		this.control.setValue(item);
		this.control.markAsTouched();
		this.control.markAsDirty();
	}

	public focus(target: 'control' | 'container' = 'control'): void {
		if (target === 'control') {
			this.listBuilderComponent.focusOnInput()
		} else {
			throw new Error('Method not implemented.');
		}
	}
}